{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@bojackduy/opencode-db-client",
  "version": "0.1.0",
  "description": "Read-only database ER canvas for the terminal: an OpenCode v1/v2 plugin and a standalone `dbcanvas` app in one package.",
  "type": "module",
  "license": "AGPL-3.0-or-later",
  "private": false,
  "repository": {
    "type": "git",
    "url": "git+https://github.com/bojackduy/opencode-db-client.git"
  },
  "homepage": "https://github.com/bojackduy/opencode-db-client#readme",
  "bugs": {
    "url": "https://github.com/bojackduy/opencode-db-client/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "database",
    "db-client",
    "sql",
    "canvas",
    "cli",
    "opentui"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "engines": {
    "bun": ">=1.1.0"
  },
  "bin": {
    "dbcanvas": "./dist/dbcanvas.js"
  },
  "exports": {
    ".": {
      "import": "./dist/server.js"
    },
    "./server": {
      "import": "./dist/server.js"
    },
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build:server": "bun build src/server/plugin.ts --outfile dist/server.js --target bun --external @opencode-ai/plugin --external @opencode-ai/plugin/tool",
    "build:tui": "bun scripts/build-tui.ts",
    "build:standalone": "bun scripts/build-standalone.ts",
    "standalone": "bun --preload @opentui/solid/preload src/standalone/main.tsx",
    "build": "bun run clean && bun run build:server && bun run build:tui && bun run build:standalone",
    "clean": "rm -rf dist",
    "test": "bun test --preload @opentui/solid/preload",
    "prepack": "bun run typecheck && bun run test && bun run build",
    "release:patch": "bun run typecheck && bun run test && npm version patch -m \"chore: release %s\" && git push && git push origin $(git describe --tags --abbrev=0)",
    "release:minor": "bun run typecheck && bun run test && npm version minor -m \"chore: release %s\" && git push && git push origin $(git describe --tags --abbrev=0)",
    "release:major": "bun run typecheck && bun run test && npm version major -m \"chore: release %s\" && git push && git push origin $(git describe --tags --abbrev=0)"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.4.0 <3",
    "@opentui/core": "*",
    "@opentui/solid": "*",
    "solid-js": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.32",
    "@opencode/plugin": "^2.0.18",
    "@opentui/core": "^0.5.12",
    "@opentui/solid": "^0.5.12",
    "@types/bun": "^1.3.14",
    "@types/node": "^26.2.0",
    "solid-js": "1.9.12",
    "typescript": "^5.7.0"
  }
}
